package com.xjtu.iron.idempotent.api.repository;import java.time.*;public final class IdempotencyFailureRequest{private final String namespace,key,ownerToken;private final long version;private final IdempotencyFailureInfo failure;private final Duration recordTtl;private final Instant now;public IdempotencyFailureRequest(String namespace,String key,String ownerToken,long version,IdempotencyFailureInfo failure,Duration recordTtl,Instant now){this.namespace=namespace;this.key=key;this.ownerToken=ownerToken;this.version=version;this.failure=failure;this.recordTtl=recordTtl;this.now=now;}public String getNamespace(){return namespace;}public String getKey(){return key;}public String getOwnerToken(){return ownerToken;}public long getVersion(){return version;}public IdempotencyFailureInfo getFailure(){return failure;}public Duration getRecordTtl(){return recordTtl;}public Instant getNow(){return now;}}
